nodes.script:
cat "{HMMLIST}" | sed 's/[a-zA-Z_]*+//g' | sed 's/-[a-zA-Z_]*//g' | uniq > list

python {SHARED_DIR/scripts/validateqs.py} qs.hed {HMMLIST}
python {SHARED_DIR/scripts/mirrorqs.py} qs.hed out.hed

test_sets.body:
HVite -A -D -T 1 -C {TEST_CONFIG} -H {MACROS_FILE} -H {HMMDEFS} -S {TEST_SCP} -i recout.mlf -w {WORDNET} {DICT} {HMMLIST}
HResults -A -D -s -I {MLF} {HMMLIST} recout.mlf > result.txt
python {SHARED_DIR/scripts/test/parsehtkresults.py} result.txt {o}
